import{_ as t,o as a,c as o,ag as s}from"./chunks/framework.DNmTgtHf.js";const k=JSON.parse('{"title":"Abstraction — the details","description":"","frontmatter":{},"headers":[],"relativePath":"design_patterns/foundations/oop_pillars/abstraction/Abstraction.md","filePath":"design_patterns/foundations/oop_pillars/abstraction/Abstraction.md"}'),i={name:"design_patterns/foundations/oop_pillars/abstraction/Abstraction.md"};function n(r,e,l,c,d,h){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="abstraction-—-the-details" tabindex="-1">Abstraction — the details <a class="header-anchor" href="#abstraction-—-the-details" aria-label="Permalink to &quot;Abstraction — the details&quot;">​</a></h1><blockquote><p>One of the four OOP pillars. Often confused with encapsulation — they are different things.</p></blockquote><hr><h2 id="two-senses-of-the-word-often-conflated" tabindex="-1">Two senses of the word (often conflated) <a class="header-anchor" href="#two-senses-of-the-word-often-conflated" aria-label="Permalink to &quot;Two senses of the word (often conflated)&quot;">​</a></h2><ol><li><strong>Conceptual abstraction</strong> — hiding <em>how</em> behind <em>what</em>. A <code>List</code> abstracts over array vs linked list internals. <code>HiringProcess.onboard()</code> abstracts over whether you&#39;re hiring Android or Backend. The caller doesn&#39;t need to know the mechanism.</li><li><strong>Java abstraction mechanisms</strong> — the <code>abstract</code> keyword, <code>interface</code>. These are the <em>tools</em> for expressing conceptual abstraction. The concept exists independently of the keyword.</li></ol><p>Confusing the two leads to mistakes like &quot;we have an interface therefore we have good abstraction&quot; — an interface whose single implementation is obvious and never swapped is just boilerplate, not meaningful abstraction.</p><hr><h2 id="abstraction-vs-encapsulation-—-they-are-different" tabindex="-1">Abstraction vs Encapsulation — they are different <a class="header-anchor" href="#abstraction-vs-encapsulation-—-they-are-different" aria-label="Permalink to &quot;Abstraction vs Encapsulation — they are different&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Abstraction</th><th>Encapsulation</th></tr></thead><tbody><tr><td>Hides</td><td>Complexity — you don&#39;t need to know <em>how</em></td><td>Internal state — you can&#39;t <em>touch</em> this directly</td></tr><tr><td>Achieved by</td><td>Interfaces, abstract classes, naming</td><td>Access modifiers, private fields, constructors</td></tr><tr><td>Analogy</td><td>Car steering wheel — you don&#39;t need to know the steering column mechanics</td><td>Locked dashboard — you cannot access the internals directly</td></tr><tr><td>Goal</td><td>Simplify the caller&#39;s mental model</td><td>Protect internal consistency</td></tr></tbody></table><p>Both work together. A <code>JobOffer</code> class <em>encapsulates</em> its fields (private, validated) and <em>abstracts</em> the concept of a job offer (callers work with salary and bonuses, not raw database rows).</p><hr><h2 id="leaky-abstraction" tabindex="-1">Leaky abstraction <a class="header-anchor" href="#leaky-abstraction" aria-label="Permalink to &quot;Leaky abstraction&quot;">​</a></h2><p>An abstraction leaks when the caller&#39;s code depends on something the abstraction was supposed to hide. The test: <strong>if you swap the implementation behind the abstraction, do callers break?</strong> If yes, leaky.</p><h3 id="joel-s-law" tabindex="-1">Joel&#39;s Law <a class="header-anchor" href="#joel-s-law" aria-label="Permalink to &quot;Joel&#39;s Law&quot;">​</a></h3><p>Joel Spolsky&#39;s <em>Law of Leaky Abstractions</em> (2002): <strong>all non-trivial abstractions, to some degree, are leaky.</strong> That&#39;s not pessimism — it&#39;s a calibration. The goal isn&#39;t perfection; it&#39;s deciding which leaks you can live with and which you make explicit in the contract.</p><h3 id="four-flavors-of-leak" tabindex="-1">Four flavors of leak <a class="header-anchor" href="#four-flavors-of-leak" aria-label="Permalink to &quot;Four flavors of leak&quot;">​</a></h3><p><strong>1. Type leaks — caller has to cast.</strong></p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Object </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getItem</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> i);          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// leaks: caller must cast</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">List</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">String</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> getItem</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> i);    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// doesn&#39;t leak</span></span></code></pre></div><p>Casts are the most visible leak. The abstraction is screaming &quot;you actually need to know what&#39;s inside me.&quot; Same for raw types and downcasts on supposedly polymorphic returns.</p><p><strong>2. Performance leaks — Big-O bleeds through.</strong></p><p><code>ArrayList</code> and <code>LinkedList</code> both implement <code>List</code>; both satisfy <code>get(i)</code>. But <code>ArrayList.get</code> is O(1) and <code>LinkedList.get</code> is O(n). Code in tight loops encodes the assumption silently — swap the implementation and the code is correct but unusably slow. The compiler can&#39;t catch this; only documentation can.</p><p><strong>3. Behavioral leaks — exceptions, threading, mutation, ordering.</strong></p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">List&lt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Integer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; immutable </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> List.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">of</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">immutable.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// compiles; UnsupportedOperationException at runtime</span></span></code></pre></div><p>The type is <code>List</code>, but the underlying mutability/thread-safety/iteration-order/exception-types vary by implementation: <code>HashMap</code> vs <code>ConcurrentHashMap</code>, <code>HashSet</code> vs <code>LinkedHashSet</code> vs <code>TreeSet</code>, a <code>Repository</code> that throws <code>SQLException</code> from one impl and <code>MongoTimeoutException</code> from another. The compiler can&#39;t catch any of this; the contract has to spell it out.</p><p><strong>4. Network/IO leaks — distance and failure bleed through.</strong></p><p>A &quot;remote object&quot; call or ORM lazy-load looks like a method call but actually involves network latency, retries, and timeouts. JPA&#39;s <code>user.getOrders()</code> looks free; in production it&#39;s an N+1 query problem. The relational/network reality leaks through as performance.</p><h3 id="quick-detection-test" tabindex="-1">Quick detection test <a class="header-anchor" href="#quick-detection-test" aria-label="Permalink to &quot;Quick detection test&quot;">​</a></h3><p>Walk through these on any API you&#39;re using or designing:</p><ul><li>Can callers swap one implementation for another without code changes? <em>No → leaky.</em></li><li>Are they relying on specific exceptions, ordering, performance, threading, or null behaviour the type doesn&#39;t promise? <em>Yes → leaky.</em></li><li>Do they ever cast or <code>instanceof</code>-check a return value? <em>Yes → very likely leaky.</em></li><li>Does the abstraction have &quot;footguns&quot; — runtime exceptions for operations that compile fine? <em>Yes → leaky (the type system is over-promising).</em></li></ul><h3 id="what-to-do-anyway" tabindex="-1">What to do anyway <a class="header-anchor" href="#what-to-do-anyway" aria-label="Permalink to &quot;What to do anyway&quot;">​</a></h3><p>The lesson isn&#39;t <em>don&#39;t abstract.</em> It&#39;s:</p><ul><li><strong>Make likely leaks explicit in the contract.</strong> Document Big-O, threading, ordering, exception types — they&#39;re part of the API even when the type system can&#39;t enforce them. <code>ArrayList</code>&#39;s docs publish &quot;constant-time random access&quot; for exactly this reason.</li><li><strong>Pick the right abstraction level for callers.</strong> <code>List</code> for iteration, <code>Stream</code> for lazy composition, <code>Page&lt;T&gt;</code> for paging. Wrong level → callers fight the abstraction → leaks.</li><li><strong>Return the narrowest interface that satisfies the use case</strong> (Effective Java Item 64). Don&#39;t return <code>ArrayList</code> if <code>List</code> would do; don&#39;t return <code>Object</code>.</li><li><strong>Beware &quot;magic&quot; abstractions</strong> — Spring&#39;s <code>@Transactional</code> silently fails on self-invocation through <code>this.method()</code> because the proxy isn&#39;t involved. Magic that hides too much usually leaks somewhere unexpected.</li></ul><p>See <code>LeakyVsCleanAbstraction.java</code> in this folder for the cast-test in code.</p><hr><h2 id="levels-of-abstraction-in-this-repo" tabindex="-1">Levels of abstraction in this repo <a class="header-anchor" href="#levels-of-abstraction-in-this-repo" aria-label="Permalink to &quot;Levels of abstraction in this repo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Level</th><th>Example</th><th>What it hides</th></tr></thead><tbody><tr><td>Interface</td><td><code>HiringProcess</code>, <code>FurnitureSetFactory</code>, <code>Employee</code></td><td>Entire implementation — callers know nothing concrete</td></tr><tr><td>Abstract class</td><td><code>DeveloperHiringProcess</code></td><td>The template (onboard flow) — exposes only the <code>createDeveloper()</code> hook</td></tr><tr><td>Concrete class</td><td><code>AndroidHiringProcess</code>, <code>CheapChair</code></td><td>Nothing further — this is the implementation</td></tr></tbody></table><p>GoF&#39;s first design principle: <em>program to an interface, not an implementation.</em> In practice: hold the most abstract type that still gives you what you need.</p><ul><li><code>HR</code> holds <code>HiringProcess</code>, not <code>AndroidHiringProcess</code> — it only needs <code>onboard()</code>.</li><li><code>furnishRoom</code> takes <code>FurnitureSetFactory</code>, not <code>CheapFurnitureFactory</code> — it only needs <code>createChair()</code> and <code>createSofa()</code>.</li><li>The loop in <code>PolymorphicPrototypeRun</code> holds <code>List&lt;Shape&gt;</code>, not <code>List&lt;Circle&gt;</code> — it only needs <code>clone()</code>.</li></ul><hr><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. Abstraction vs encapsulation in two sentences (no shared &quot;hide&quot;)?</strong> A. Abstraction simplifies what callers must understand by exposing only the <em>what</em>, not the <em>how</em>. Encapsulation protects internal state by controlling who can read or modify it.</p><p><strong>Q. The one-line test for a leaky abstraction?</strong> A. If swapping the implementation forces callers to change, the abstraction leaks.</p><p><strong>Q. Joel&#39;s Law?</strong> A. All non-trivial abstractions, to some degree, leak. Pick which leaks you tolerate and document the rest.</p><p><strong>Q. Why is <code>Object getItem(int)</code> leakier than <code>String getItem(int)</code>?</strong> A. <code>Object</code> forces callers to cast, which means they must know the actual stored type — the storage decision is no longer hidden.</p><p><strong>Q. &quot;Program to an interface, not an implementation&quot; — what does that look like in this repo?</strong> A. Hold the most abstract type that still does the job. <code>HR</code> holds <code>HiringProcess</code> (not <code>AndroidHiringProcess</code>); <code>furnishRoom</code> takes <code>FurnitureSetFactory</code> (not <code>CheapFurnitureFactory</code>); the loop in <code>PolymorphicPrototypeRun</code> holds <code>List&lt;Shape&gt;</code> (not <code>List&lt;Circle&gt;</code>).</p><hr><h2 id="related-topics" tabindex="-1">Related topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related topics&quot;">​</a></h2><ul><li><strong>Encapsulation</strong> — its frequently-confused sibling.</li><li><strong>Abstract Class vs Interface</strong> — the Java mechanics for expressing abstraction.</li><li><strong>SOLID — DIP</strong> — &quot;depend on abstractions&quot; makes &quot;what <em>is</em> an abstraction in this code?&quot; a real question.</li></ul>`,48)])])}const u=t(i,[["render",n]]);export{k as __pageData,u as default};
